head.script:
scwin.onpageload = function() {
requires("uiplugin.popup"); 	
};

scwin.openPop = function(type) {
    var options = {  

            id : "popup1", 
            type : "wframePopup", 
            width: "230px", 
            height: "250px", 
            top: "130px", 
            left: "200px", 
            popupName : "testPopup", 
            modal : true, 
            resizable : true, 
            status : true, 
            menubar : false, 
            scrollbars : false, 
            title : false,
            accessibility :true//,
            //disableCloseButton : true

        }; 

        // 팝업 생성.

        $p.openPopup("popup_tabmove_disable_WESD-1768_(WSQ-5865)_"+type+".xml",  options );
};

